 gate=json.loads((O/'PHOTOSHOP_GATE.json').read_text());assert gate['PASS'];integrity=json.loads((O/'NATIVE_INTEGRITY.json').read_text());visual=json.loads((O/'FINAL_NATIVE_VISUAL_QA.json').read_text());decision=json.loads((O/'SCIENTIFIC_DECISION.json').read_text());utc=datetime.now(timezone.utc).isoformat();back=O/'docs_before_final';back.mkdir(exist_ok=True)
