 record={'utc':utc,'status':'DELIVERED_BOUNDED_IMPROVEMENT_NOT_ALL_LIMB_ARTIFACTS_VALIDATED','path':'1-PHOTOSHOP/V85.psb','sha256':gate['sha256'],'bytes':gate['bytes'],'canvas':[10551,7506],'depth':16,'layers':42,'photoshop_gate':gate['result'],'source':'1-PHOTOSHOP/V84.psb','source_sha256':integrity['input_sha256'],'source_unchanged':True,'regenerated_filter_layers':17,'regenerated_distinct_mounted_rasters':16,'moon_composite_exact':True,'green_mark_red_clipping_percent_before_after':[visual['original_unfiltered_red_clip_percent'],visual['final_red_clip_percent']],'all_artifacts_resolved':False,'universal_scientific_PASS':False,'full_RAW_to_PSB_deterministic':False,'report':'4-RESULTATS/v85_regeneracio_20260922/RESULTAT.md','receipt':'1-PHOTOSHOP/V85_REBUT.md','scientific_decision':'4-RESULTATS/v85_regeneracio_20260922/SCIENTIFIC_DECISION.json','code':'3-RECERCA/tools/v85_regeneracio_20260922','handoff':'.coordination/HANDOFF_2026-09-22_V85.md','limits':'Near-limb injected-detail transfer remains outside predefined bounds; no complete artifact-free limb claim. WOW bilateral angular broad-band Brno morphology slightly regresses.'}
